// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IBaseManager} from "./IBaseManager.sol";
import {IPerpAsset} from "./IPerpAsset.sol";
import {IOptionAsset} from "./IOptionAsset.sol";

interface ILiquidatableManager is IBaseManager {
  /**
   * @notice can be called by anyone to settle all perp asset in an account
   */
  function settlePerpsWithIndex(uint accountId) external;

  /**
   * @notice can be called by anyone to settle option assets in an account
   */
  function settleOptions(IOptionAsset _option, uint accountId) external;

  /**
   * @dev get initial margin or maintenance margin
   */
  function getMargin(uint accountId, bool isInitial) external view returns (int);

  function getMarginAndMarkToMarket(uint accountId, bool isInitial, uint scenarioId) external view returns (int, int);
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

/**
 * @title IForwardFeed
 * @author Lyra
 * @notice return forward feed for 1 asset
 */

interface IForwardFeed {
  /**
   * @notice Gets forward price for a particular asset
   * @param expiry Forward expiry to query
   */
  function getForwardPrice(uint64 expiry) external view returns (uint forwardPrice, uint confidence);
  function getForwardPricePortions(uint64 expiry)
    external
    view
    returns (uint forwardFixedPortion, uint forwardVariablePortion, uint confidence);
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IManager} from "./IManager.sol";

interface IPositionTracking {
  /////////////////
  //   Structs   //
  /////////////////

  struct OISnapshot {
    bool initialized;
    uint240 oi;
  }

  function setTotalPositionCap(IManager manager, uint oiCap) external;

  function totalPositionCap(IManager manager) external view returns (uint);

  function totalPositionBeforeTrade(IManager manager, uint tradeId) external view returns (bool, uint240);

  function totalPosition(IManager manager) external view returns (uint);

  /// @dev Emitted when snapshot is taken for totalOi
  event SnapshotTaken(address manager, uint tradeId, uint oi);

  /// @dev Emitted when OI cap is set
  event TotalPositionCapSet(address manager, uint oiCap);

  /// @dev Reverts if total position exceeds cap
  error PT_CapExceeded();
}

